import { cn } from '@/lib/utils';

/**
 * Brand logos for integrations (Settings tiles, side sheets, the city ×
 * courier grid). ONE component for every third-party mark in the app.
 *
 * - `mark` brands are single-colour Simple Icons glyphs (simple-icons@13.21.0)
 *   drawn white on the brand colour.
 * - Courier logos are the official wordmarks from each courier's website,
 *   trimmed + resized into `public/brands/<courier>.png`. PostEx and RapidXpk
 *   only publish white wordmarks, so their plate is dark.
 */

export type MarkBrand =
  | 'whatsapp'
  | 'meta'
  | 'shopify'
  | 'woocommerce'
  | 'openai'
  | 'anthropic'
  | 'gdrive';

export type CourierBrand =
  | 'trax'
  | 'leopards'
  | 'postex'
  | 'mnp'
  | 'rocket'
  | 'rapidxpk'
  | 'tcs';

