const COURIERS: Record<CourierBrand, { label: string; dark: boolean }> = {
  trax: { label: 'Trax', dark: false },
  leopards: { label: 'Leopards', dark: false },
  postex: { label: 'PostEx', dark: true },
  mnp: { label: 'M&P', dark: false },
  rocket: { label: 'Rocket', dark: false },
  rapidxpk: { label: 'RapidXpk', dark: true },
  tcs: { label: 'TCS', dark: false },
};

export function isCourierBrand(v: string): v is CourierBrand {
  return v in COURIERS;
}

const MARK_SIZES = {
  sm: 'h-7 w-7 rounded-lg [&>svg]:h-4 [&>svg]:w-4',
  md: 'h-10 w-10 rounded-xl [&>svg]:h-[22px] [&>svg]:w-[22px]',
  lg: 'h-12 w-12 rounded-xl [&>svg]:h-[26px] [&>svg]:w-[26px]',
};

/** Square brand mark (white glyph on the brand colour). */
export function BrandMark({
  brand,
  size = 'md',
  className,
}: {
  brand: MarkBrand;
  size?: keyof typeof MARK_SIZES;
  className?: string;
}) {
  const m = MARKS[brand];
  return (
    <span
      role="img"
      aria-label={m.label}
      className={cn(
        'inline-grid shrink-0 place-items-center',
        m.bg === '#FFFFFF' && 'border border-line',
        MARK_SIZES[size],
        className,
      )}
      style={{ backgroundColor: m.bg }}
    >
      <svg viewBox="0 0 24 24" fill={m.fg ?? '#fff'} aria-hidden="true">
        <path d={m.path} />
      </svg>
    </span>
  );
}

const PLATE_SIZES = {
  xs: 'h-7 w-[78px] rounded-md px-1.5 [&>img]:max-h-[18px]',
  sm: 'h-11 w-28 rounded-lg px-2.5 [&>img]:max-h-[30px]',
  lg: 'h-14 w-36 rounded-xl px-3 [&>img]:max-h-[38px]',
};

/** Courier wordmark on a light (or dark, for white logos) plate. */
export function CourierLogo({
  courier,
  size = 'sm',
  className,
}: {
  courier: CourierBrand;
  size?: keyof typeof PLATE_SIZES;
  className?: string;
}) {
  const c = COURIERS[courier];
  return (
    <span
      className={cn(
        'inline-grid shrink-0 place-items-center',
        c.dark ? 'bg-[#121417]' : 'border border-line bg-white',
        PLATE_SIZES[size],
        className,
      )}
    >
      {/* eslint-disable-next-line @next/next/no-img-element -- tiny static asset, no optimisation needed */}
      <img
        src={`/brands/${courier}.png`}
        alt={`${c.label} logo`}
        className="block max-w-full object-contain"
        loading="lazy"
      />
    </span>
  );
}
